      "ar": "يَٰبَنِي ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِي سَوْءَٰتِكُمْ وَرِيشًا وَلِبَاسُ التَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ ءَايَٰتِ اللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ",
